class Solution {
public:
    int findMiddleIndex(vector<int>& nums) {
        for (int i = 0; i < (int)nums.size(); ++i) {
            int left = accumulate(nums.begin(), nums.begin() + i, 0);
            int right = accumulate(nums.begin() + i + 1, nums.end(), 0);
            if (left == right) return i;
        }
        return -1;
    }
};

